    private static final int RECORD_HEADER_SIZE = 25;
    private static final int RECORDS_PER_CHUNK = 200_000;
    private static final long INITIAL_CHECKSUM = 0x5deece66dL;

    private static final Comparator<byte[]> RECORD_ORDER = Reconciler::compareRecords;

    public static void reconcile(Path input, Path report) throws IOException {
        Path work = null;
        try {
            work = Files.createTempDirectory("ledger-reconciliation-");
            EventSorter sorter = new EventSorter(work.resolve("chunks"));
            long eventCount = stage(input, sorter);
            sorter.finish();

            try (BufferedWriter writer = Files.newBufferedWriter(report, StandardCharsets.UTF_8);
                 MergeIterator events = sorter.merge()) {
                writer.write("events|");
                writer.write(Long.toString(eventCount));
                writer.write('\n');
                aggregate(events, writer);
            }
        } finally {
            if (work != null) {
                deleteTree(work);
            }
        }
