    private static long stage(Path input, EventSorter sorter) throws IOException {
        long previousSequence = -1;
        long eventCount = 0;
        long lineNumber = 0;
        try (BufferedReader reader = Files.newBufferedReader(input, StandardCharsets.UTF_8)) {
            String line;
            while ((line = reader.readLine()) != null) {
                lineNumber++;
                EventLog.Event event = EventLog.parse(line, lineNumber);
                if (event.sequence() <= previousSequence) {
                    throw new IllegalArgumentException("sequence order at line " + lineNumber);
                }
                previousSequence = event.sequence();
                sorter.add(event.timestamp(), event.sequence(), event.amount(), event.account());
                eventCount++;
            }
        }
        if (eventCount == 0) {
            throw new IllegalArgumentException("empty log");
        }
        return eventCount;
    }

    private static void aggregate(MergeIterator events, BufferedWriter writer) throws IOException {
        AccountState state = new AccountState();
        byte[] account = null;
        byte[] record;
        while ((record = events.next()) != null) {
            if (account != null && !sameAccount(account, record)) {
                writeSummary(writer, account, state);
                state.reset();
            }
            if (state.count == 0) {
                int length = record[24] & 0xff;
                account = Arrays.copyOfRange(record, RECORD_HEADER_SIZE, RECORD_HEADER_SIZE + length);
            }
            long sequence = longAt(record, 8);
            long timestamp = longAt(record, 0);
            long amount = longAt(record, 16);

            state.count++;
            state.total = Math.addExact(state.total, amount);
            if (state.firstSequence < 0) {
                state.firstSequence = sequence;
                state.firstTimestamp = timestamp;
                state.lastSequence = sequence;
                state.lastTimestamp = timestamp;
            } else {
                if (sequence < state.firstSequence) {
                    state.firstSequence = sequence;
                    state.firstTimestamp = timestamp;
