        StringBuilder line = new StringBuilder(account.length + 96);
        for (int i = 0; i < account.length; i++) {
            line.append((char) (account[i] & 0xff));
        }
        line.append('|').append(state.count).append('|')
                .append(state.total).append('|')
                .append(state.firstSequence).append('|')
                .append(state.lastSequence).append('|')
                .append(state.firstTimestamp).append('|')
                .append(state.lastTimestamp).append('|')
                .append(state.checksum);
        writer.write(line.toString());
        writer.write('\n');
