    private static int compareRecords(byte[] left, byte[] right) {
        int leftLength = left[24] & 0xff;
        int rightLength = right[24] & 0xff;
        int comparison = Arrays.compareUnsigned(left, RECORD_HEADER_SIZE, RECORD_HEADER_SIZE + leftLength,
