    private static final class EventSorter implements AutoCloseable {
        private final Path directory;
        private final ArrayList<byte[]> chunk = new ArrayList<>(RECORDS_PER_CHUNK);
        private int chunkCount;

        private EventSorter(Path directory) throws IOException {
            this.directory = directory;
            Files.createDirectories(directory);
